using FinancialManager.Domain.Accounts;
using FinancialManager.Domain.Common;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace FinancialManager.Infrastructure.Persistence.Configurations;

internal sealed class HoldingConfiguration : IEntityTypeConfiguration<Holding>
{
    public void Configure(EntityTypeBuilder<Holding> builder)
    {
        builder.ToTable("Holdings");
        builder.HasKey(h => h.Id);

        // Keys are generated by the domain, so EF must treat unseen keys as new rows.
        builder.Property(h => h.Id).ValueGeneratedNever();

        builder.Property(h => h.Symbol).HasMaxLength(DomainLimits.SymbolMaxLength).IsRequired();
        builder.Property(h => h.Quantity).HasPrecision(DomainLimits.QuantityPrecision, DomainLimits.QuantityScale);
        builder.Property(h => h.AverageCostPerShare).HasPrecision(DomainLimits.QuantityPrecision, DomainLimits.UnitPriceScale);
        builder.Ignore(h => h.CostBasis);

        builder.HasIndex(h => new { h.AccountId, h.Symbol }).IsUnique();
    }
}
